"""Inference exercises: explicit deductions, truth tables and checked resolution paths."""
import itertools
import manual_solutions as author
from logic_proofs import Formula

def put(n,steps,errors):
 author.add('DM2T',f'003-{n:03}',steps,errors,'逐小问检查前提、结论、推理方法、附加假设的解除及反例；消解逐步核验。')
def example(n,steps,errors):
 author.add_example('DM2T',n,steps,errors,'逐步推理并用全赋值核对有效性，所需消解步骤严格按单对互补文字执行。')
def inference(premises,goal):
 fs=[Formula(s,7) for s in premises];g=Formula(goal,7)
 variables=sorted(set(g.variables+sum([f.variables for f in fs],[])))
 rows=[]
 for bits in itertools.product([0,1],repeat=len(variables)):
  env=dict(zip(variables,bits));pv=[f.ev(f.tree,env) for f in fs];P=int(all(pv));C=g.ev(g.tree,env)
  rows.append((bits,pv,P,C,int(not P or C)))
 return variables,rows
def table(premises,goal):
 variables,rows=inference(premises,goal)
 headers=variables+['P_'+str(i+1) for i in range(len(premises))]+['P','C',r'P\to C']
 body=r'\begin{array}{'+'c'*len(headers)+'}'+'&'.join(headers)+r'\\\hline '
 body+=r'\\'.join('&'.join(map(str,list(bits)+pv+[P,C,I])) for bits,pv,P,C,I in rows)+r'\end{array}'
 return '按共同变项顺序 $'+','.join(variables)+'$ 列齐全部赋值。Pᵢ依次为各前提，P是它们的合取，C是结论：$$'+body+'.$$',rows
def valid(premises,goal):
 variables,rows=inference(premises,goal)
 return not any(P and not C for bits,pv,P,C,I in rows)
def pdnf(rows,col):
 ids=[i for i,row in enumerate(rows) if row[col]]
 return r'\lor '.join('m_{'+str(i)+'}' for i in ids) or '0'
def resolvent(clauses,path):
 # Literals use a leading '-' for negation; every supplied pivot is checked.
 C=[frozenset(x) for x in clauses]
 def opposite(x):return x[1:] if x.startswith('-') else '-'+x
 def tex(c):return r'\lor '.join((r'\neg '+x[1:] if x.startswith('-') else x) for x in sorted(c,key=lambda x:(x.lstrip('-'),x.startswith('-')))) or r'\square'
 out=['先合取全部前提与结论的否定，消去箭头、双条件，再把合取拆为以下子句：$$'+r',\quad '.join('C_{'+str(i)+'}='+tex(c) for i,c in enumerate(C,1))+'.$$']
 for a,b,pivot in path:
  A,B=C[a-1],C[b-1]
  assert pivot in A and opposite(pivot) in B
  R=(A-{pivot})|(B-{opposite(pivot)});C.append(frozenset(R))
  out.append('对 $C_{'+str(a)+'}$ 与 $C_{'+str(b)+'}$ 的 $'+tex({pivot})+'$、$'+tex({opposite(pivot)})+'$ 消解，只删这一对，合并其余文字并去重，得 $$C_{'+str(len(C))+'}='+tex(R)+'.$$')
 assert not C[-1]
 out+=['最后得到空子句，任何赋值都不能满足它。每次消解都是原子句集的逻辑后果，所以“前提且结论否定”不可满足，即不存在前提全真而结论假的赋值，原推理有效。']
 return out

put(1,[r'附加律形式是p⊨p∨q：已断定p后，加入任意另一个分支q的析取仍真。它不是从p推q，也不是让p、q恰好一个真。',r'例一设p为“我读过这本书”、q为“我看过同名电影”。前提p，结论p∨q。若前提真，析取至少已有真分支p，故结论真，无需知道是否看过电影。',r'例二设p为“6是偶数”、q为“6是素数”。前提p真，q事实上假，但p∨q=1∨0=1，故仍是有效推理。两个实例均满足相同附加律。'],[r'附加出的q不必本身为真，不能把析取结论误读成单独断定q。',r'本题“或”是相容析取。'])
put(2,[r'化简律从合取推出任一因子：p∧q⊨p，也有p∧q⊨q。合取只有两项都真时真，所以两种结论都被前提保证。',r'例一设p为“小张会英语”、q为“小张会日语”。前提p∧q，结论p；语句为“小张两种都会，所以他会英语”。',r'例二设p为“12>10”、q为“12是偶数”。前提p∧q，结论q；两个前提事实均真，结论也真。化简只是取出已经被同时断定的一个分句。'],[r'化简律用于合取，不能从p∨q直接推出p。',r'两个实例各自定义字母，定义不能在一个实例中途更换。'])
put(3,[r'假言推理（肯定前件）需要两个前提p→q和p；要使p→q在p真时仍真，q必须真，所以结论q被保证。',r'例一设p为“下雨”、q为“地面湿”，将“若下雨则地面湿；正在下雨；故地面湿”写为p→q、p⊨q。这里条件句作为给定前提，不是在另行证明气象规律。',r'例二设p为“8是4的倍数”、q为“8为偶数”。条件由8=4×2=2×4满足；再有p，推出q。形式仍是(p→q)∧p⊨q。',r'例三设p为“按时交作业”、q为“获得作业分”，把给定的评分规则p→q与已经按时交作业p合用，推出q。三例都不能仅凭q反推p，那会变成肯定后件。'],[r'必须同时有条件句和前件，只有p→q本身不能无条件推出q。',r'肯定后件是另一种一般无效的形式，不是本题定律。'])
put(4,[r'拒取式：设p为设备通电、q为指示灯亮，前提p→q、¬q。若p真就会q真，与¬q冲突，故¬p；形式(p→q)∧¬q⊨¬p，设备规则在例中作为已给条件。',r'析取三段论：p为在教室、q为在图书馆。p∨q与¬p迫使q真，因此“在教室或图书馆；不在教室；故在图书馆”有效。即使析取可相容，排掉p后仍可推出q。',r'假言三段论：对一个固定整数，p为4的倍数、q为偶数、r为能被2整除。从p→q、q→r得p→r：若临时假设p，就依次得q、r，再解除p。',r'等价三段论：p为整数n偶数、q为n能被2整除、r为n除以2余0。由p↔q和q↔r，p真可逐次推出r，r真也可逐次反推p，所以得p↔r。',r'构造性二难：p为下雨、q为晴天、r为带伞、s为戴帽。前提p→r、q→s、p∨q；若p分支得r从而r∨s，若q分支得s从而r∨s，两个前提允许的分支都保证同一结论，所以得r∨s。'],[r'构造性二难需要p∨q这个分支覆盖前提，不能只给两个条件句。',r'双条件的传递要保留两个方向，单向链只得蕴涵。'])
put(5,[r'若A↔B为重言等值式，则A真必B真、B真必A真，所以产生A⊨B和B⊨A两条推理。这里是把同一等值关系分别取两个方向，不能只列一条。',r'德摩根第一式¬(p∧q)↔(¬p∨¬q)产生两条；第二式¬(p∨q)↔(¬p∧¬q)也产生两条。分别表达“并非都真”与“都不真”，两种否定范围不同，合计四条。',r'吸收第一式p∨(p∧q)↔p，前式含p已足，反向由p附加出该析取，产生两条；第二式p∧(p∨q)↔p，前式化简得p，反向由p附加得p∨q再合取，另有两条。',r'答案共八条，按每个等值式左右互换分别书写即可。吸收律反向也有效，是因为附加的含q结构已由p保证，并不是从p推出单独q。'],[r'德摩根的两种形式要一起处理，每个又有两个推理方向。',r'吸收律反向不允许推出q本身。'])

forms=[([r'p\to q','p'],'q'),([r'p\to q','q'],'p'),([r'p\to q',r'\neg q'],r'\neg p'),([r'p\to q',r'\neg p'],r'\neg q'),([r'p\to(q\lor r)','p'],'q'),([r'p\leftrightarrow q',r'\neg p'],r'\neg q')]
steps=[r'本题检验推理形式，不以“星期一到明天”的现实日历关系替代逻辑赋值。每问把“今天星期一”设p，q按该问为明天星期二或三，第（5）另设q为星期二、r为星期三。有效要求所有前提全真时结论必真，等价于前提合取蕴涵结论为重言式。']
reasons=[r'第（1）前提p→q、p，结论q，是假言推理。前提合取化为p∧q，故总蕴涵¬(p∧q)∨q=¬p∨¬q∨q=1。前提的日历事实可能不真，不影响该形式的有效性。',r'第（2）前提p→q、q，结论p，肯定后件。化简总蕴涵为p∨¬q；pq=01使两前提真而p假，所以无效。',r'第（3）前提p→q、¬q，结论¬p，为拒取式。前提合取等于¬p∧¬q，必有¬p，所以总蕴涵恒真。',r'第（4）前提p→q、¬p，结论¬q，否定前件。前提合取只要求¬p，不能决定q；总蕴涵p∨¬q在01为假，所以无效。',r'第（5）前提p→(q∨r)、p，结论q。两前提只得q∨r，不能删去r分支；化简总蕴涵¬p∨q∨¬r，pqr=101为反例。',r'第（6）前提p↔q、¬p，结论¬q。先从双条件得q→p，再拒取得¬q；前提合取化为¬p∧¬q，所以总蕴涵恒真。']
for i,((premises,goal),why) in enumerate(zip(forms,reasons),1):
 text,rows=table(premises,goal);steps+=[why,text]
 assert valid(premises,goal)==(i in [1,3,6])
put(6,steps,[r'前提事实不真与推理形式无效不是一回事，第（1）为有效但并不保证前提真实。',r'第（2）、（4）不能交换或否定前件；第（5）不能从析取任取一项。'])

put(7,[r'第（1）有效结论p→r：附加p，由p→q得q、再q→r得r，解除p。选无效结论p，赋值000使两个条件句都真而p假，故确实不被前提保证。',r'第（2）有效结论¬p：暂设p，与前提q合取得p∧q，再由条件得r，与¬r矛盾，所以¬p。无效结论选r，pqr=010使三个前提全真而r假。',r'第（3）有效结论r：由p→(q→r)与p得q→r，再用q得r。无效结论¬r，111满足全部前提而使¬r假。',r'每小问都同时给出有效推导与无效反例；无效不是说结论在任何情形都假，只说存在前提真时结论假。'],[r'无效结论的反例必须让该组全部前提真，不能只满足一条。',r'在第（2）附加p得到矛盾后才可断定¬p。'])
put(8,[r'统一设h为天气热、t为有时间、s为游泳。第（1）“只有热才游泳”是s→h，再有s，肯定前件得h。选无效结论¬h，以s=h=1为反例，前提全真而¬h假。',r'第（2）“只要热就游泳”为h→s，再有¬s，拒取得¬h。无效结论h用h=s=0反驳：条件句因前件假而真，¬s真，但h假。',r'第（3）“除非热且有时间才游泳”写s→(h∧t)；“不热或没时间”为¬h∨¬t=¬(h∧t)。由拒取式得¬s；若选s作结论，h=t=s=0满足两前提却使s假。',r'三问都先按充分、必要条件定箭头，再使用定律，不把日常“只有”“只要”的位置凭字面相同处理。'],[r'“只有h才s”是s→h，“只要h就s”是h→s。',r'¬h∨¬t是否定整个h∧t，不表示二者必须都假。'])

premises=[r'p\to\neg q',r'r\to q'];goal=r'r\to\neg p';text,rows=table(premises,goal)
put(9,[r'设p为a奇数、q为a能被2整除、r为a偶数；两前提P₁=p→¬q、P₂=r→q，结论C=r→¬p。以下分别完成题目要求的三种方法，不只用数学常识代替逻辑验证。',r'方法一，真值表。'+text+r'全部P=1的行均有C=1，所以最后一列全1，推理有效。',r'方法二，等值演算：$P\land\neg C=(\neg p\lor\neg q)\land(\neg r\lor q)\land r\land p$。用p化简第一括号为¬q，用r化简第二括号为q，故含q∧¬q，等于0。于是P→C=¬(P∧¬C)=1。',r'方法三，按共同pqr顺序求主析取范式：$$P='+pdnf(rows,2)+r',\quad C='+pdnf(rows,3)+r'.$$P每个真行下标都在C中，即{0,2,3,4}包含于{0,1,2,3,4,6}，因此P真必C真，推理有效。'],[r'主范式比较要使用同一变项集合与顺序。',r'证明P且¬C恒假后，还须说明这等价于P→C恒真。'])
premises=[r'p\to((q\land\neg r)\lor(\neg q\land r))',r'\neg p'];goal=r'\neg q\land\neg r';text,rows=table(premises,goal)
put(10,[r'设p为ab<0、q为a<0、r为b<0。第一前提为p→((q∧¬r)∨(¬q∧r))，第二前提¬p；结论¬q∧¬r。前提合取在¬p下自动满足条件句，所以P≡¬p。',r'真值表法：'+text+r'001、010、011三行前提全真而结论假，因此最后一列不恒真，推理不正确。',r'主析取范式法：$$P='+pdnf(rows,2)+r',\quad C='+pdnf(rows,3)+r'.$$P的真行{0,1,2,3}不包含于C的{0,4}，比如下标3就是反例，故不是逻辑后果。',r'数值核查可取a=b=−1：积1不是负数，两个数却都负，故第一条件句与第二前提真、结论假，反驳甚至不需要借助零。形式错误是从否定前件企图否定后件。'],[r'ab不为负允许两个数同为负，不能仅想到都非负。',r'在形式真值表之外给具体数值反例，可检查抽象赋值是否符合原语义。'])

put(11,[r'①p与②¬p∨q作为前提已知。③从②的析取排除¬p：因①p等于¬¬p，与¬p互补，所以由①②用析取三段论得q。',r'④¬q∨r与③q同理，由③④析取三段论得⑤r；不是附加律，因为是在两个备选中排除一个。',r'⑥r→s与⑤r构成肯定前件，由假言推理得⑦s。填空依次为析取三段论、析取三段论、假言推理，各次都明确引用的两条已得命题。'],[r'析取三段论可以用p排除¬p，等价于对第一个文字取否定。',r'最后一步是条件句与前件，不是把r→s单独当作s。'])
put(12,[r'结论为(p∧q)→s，先附加假设①p∧q；②p、③q分别从①用化简律得到。这一假设只在当前子证明内部使用，不能直接当作全局前提。',r'④p→(q→r)是原前提，②④假言推理得⑤q→r；③⑤假言推理得⑥r。',r'⑦q→(r→s)为另一原前提，③⑦假言推理得⑧r→s；⑥⑧假言推理得⑨s。',r'现在已在假设p∧q下导出s，解除且仅解除这个附加假设，用条件证明得(p∧q)→s。不能在解除前把⑨当作不依赖p、q的无条件结论。'],[r'必须在最后解除附加前提，结论是蕴涵，不是单独s。',r'嵌套箭头应先由p得到q→r，再用q得到r，不能省掉一层前件。'])
put(13,[r'第一前提¬(p→q)∧q化简给q和¬(p→q)。后者用¬(p→q)≡p∧¬q，再化简得¬q，因此这组前提包含显式矛盾q、¬q。其他两个前提不需要参与就已不相容。',r'对任意目标公式A，从q用附加律得q∨A，再与¬q用析取三段论得A。两次推理都有明确依据，并不是没有证明地宣称“什么都可以”。',r'依次取A=r、A=s、A=r∨s，得到第（1）要求的三个结论；A完全任意则证明第（2）。这叫经典逻辑中的爆炸原理。',r'语义上也可检查：有效性只禁止前提全真而结论假的情况；本组根本不存在前提全真的赋值，所以任何这样的反例都不存在。这不说明现实中r或s必为真，只说明矛盾前提不能提供有区分度的知识。'],[r'不要把从不相容前提可推任意式误解成任意式都是重言式。',r'本题不能以“没用到另两个前提”为理由否定证明，已有矛盾子集就足够。'])

put(14,[
 r'以下均在自然推理系统中由已给前提逐步导出结论。若结论为蕴涵，须在一个附加假设作用域内推出后件，再解除它；若没有附加假设，则每一步只依赖原前提及此前结论。',
 r'第（1）①p、②q、③p→(q→r)是前提；④q→r由①③假言推理；⑤r由②④假言推理；⑥r∨s由⑤附加。s不必另证，因析取已经有真分支r。',
 r'第（2）①p→q、②¬(q∧r)、③r是前提；④¬q∨¬r由②德摩根；⑤¬q由③④析取三段论（用r排除¬r）；⑥¬p由①⑤拒取式，得所求。',
 r'第（3）①p→q为原前提，附加②p；③q由①②假言推理；④p∧q由②③合取引入。解除②，得⑤p→(p∧q)。原前提①仍保留，不能一并解除。',
 r'第（4）①t由t∧r化简；②t→s由s↔t取反方向；③s由①②；④s→q由q↔s取反方向；⑤q由③④；⑥p由q→p与⑤；⑦p∧q由⑥⑤。双条件两个方向都可用，本题所需方向已逐次指出。',
 r'第（5）①p、②q由p∧q分别化简；③r由p→r、①假言推理；④s由q→s、②假言推理；⑤r∧s由③④合取。',
 r'第（6）①p、②q由p∧q化简；③r由¬p∨r与①析取三段论；④s由¬q∨s与②同理；⑤r∧s由③④。附加⑥t，在该作用域内⑤仍成立，故解除⑥得到t→(r∧s)。结论不要求t在原前提中能被证出。'
],[r'结论有“或”时可用附加律，有“且”时须各分支都已得到。',r'条件证明可以使用不依赖附加假设的已得后件，但最后仍须明确解除假设。'])
put(15,[r'两小问结论都是条件句，采用附加前提法：先假设箭头前件，推到后件，再解除这次假设。证明中原有前提的作用域不变。',r'第（1）①s（附加）；②p由s→p和①；③q→r由p→(q→r)和②；④q（原前提）；⑤r由③④。于是解除①，得s→r。q是全局前提，不因解除s而失去。',r'第（2）①p（附加）；②p∨q由①附加；③r∧s由(p∨q)→(r∧s)与②；④s由③化简；⑤s∨t由④附加；⑥u由(s∨t)→u和⑤。解除①，得p→u。全过程没有把“附加律”与“附加前提”混成同一种操作。'],[r'附加律从已得命题产生析取，附加前提法则临时作假设，二者用途不同。',r'第二问不需证明r或t为真，它们只出现在可由其他分支保证的结构里。'])
put(16,[r'归谬法先假设待证结论的否定，在原前提下导出某式及其否定；解除这一附加假设，经典逻辑中得到目标结论。要展示具体矛盾，不能只写“明显矛盾”。',r'第（1）目标¬p，附加p。由p→¬q得¬q；从r∧¬s化简得r，再与¬r∨q析取三段论得q。于是q∧¬q矛盾，解除p得¬p。原前提里的¬s未用到不影响证明。',r'第（2）目标r∨s，附加¬(r∨s)，德摩根得¬r、¬s。用p→r和¬r拒取得¬p；用q→s和¬s拒取得¬q；再由p∨q与¬p得q，与¬q矛盾。解除¬(r∨s)，得到¬¬(r∨s)，双重否定得r∨s。'],[r'第（2）必须否定整个析取，得到两个否定的合取。',r'归谬临时假设要在最后解除，不能留下来作为原条件。'])
put(17,[r'设p为A到过房间、q为A在11点前离开、r为看门人看见A、s为A是嫌犯。四个原前提准确写为(p∧¬q)→s，p，q→r，¬r；目标s。特别是“没离开”是¬q。',r'先由q→r与¬r使用拒取式得到¬q。与原前提p合取得p∧¬q，这一步把第一个条件句的完整前件凑齐。',r'再由(p∧¬q)→s与已得p∧¬q假言推理，得到s。检查每个箭头均按题目给的充分条件使用，没有从看门人未见直接推“未到过房间”。',r'此处结论是题设逻辑规则下的“嫌犯”，不能将符号s擅自改成“已经证明实施犯罪”；这会改变原题结论。'],[r'未被看见可按给定q→r推出未提前离开，不能推出没有进过房间。',r'结论只到原题的“嫌犯”，不要在符号化中扩大为有罪。'])
put(18,[r'第（1）设a为星期六、b为去颐和园、c为去圆明园、d为颐和园人多。前提a→(b∨c)、d→¬b、a∧d，结论c。',r'从a∧d分别化简得a、d；用a→(b∨c)得b∨c，用d→¬b得¬b；最后析取三段论排除b得到c。各前件都来自原合取的化简，不是自行假定。',r'第（2）设p为理科生、q为数学好、r为文科生。前提p→q、¬r→p、¬q。由第一、第三条拒取得¬p；用¬r→p与¬p再拒取，结论是¬¬r；最后双重否定得r。',r'第二次拒取的前件是¬r，否定它才得到¬¬r，不能少一层否定而错误得¬r。整个证明依给定分类条件，而不是额外假定所有学生天然只有这两类。'],[r'第（1）要从a∧d取出两个事实，不能只用星期六就任取园区。',r'第（2）拒取负前件得到双重否定，必须再消去。'])

RESOLUTION_CASES=[
 ([r'p\to(q\to r)','p','q'],r'r\lor s',
  [['-p','-q','r'],['p'],['q'],['-r'],['-s']],[(2,1,'p'),(3,6,'q'),(7,4,'r')]),
 ([r'p\to q'],r'p\to(p\land q)',
  [['-p','q'],['p'],['-p','-q']],[(2,1,'p'),(2,3,'p'),(4,5,'q')]),
 ([r'q\to p',r'q\leftrightarrow s',r's\leftrightarrow t',r't\land r'],r'p\land q',
  [['-q','p'],['-q','s'],['-s','q'],['-s','t'],['-t','s'],['t'],['r'],['-p','-q']],[(6,5,'t'),(9,3,'s'),(10,1,'q'),(11,8,'p'),(10,12,'q')]),
 ([r'\neg p\lor r',r'\neg q\lor s',r'p\land q'],r't\to(r\land s)',
  [['-p','r'],['-q','s'],['p'],['q'],['t'],['-r','-s']],[(3,1,'p'),(4,2,'q'),(7,6,'r'),(8,9,'s')]),
 ([r'p\lor q',r'p\to r',r'q\to s'],r'r\lor s',
  [['p','q'],['-p','r'],['-q','s'],['-r'],['-s']],[(4,2,'-r'),(5,3,'-s'),(6,1,'-p'),(8,7,'q')])
]
steps=[r'消解证明推理时要把所有原前提与“结论的否定”合取，化为子句集，再推出空子句。不是直接把结论也当作真前提加入。以下每一问都标明初始子句与单次消解的互补对。']
for i,(premises,goal,clauses,path) in enumerate(RESOLUTION_CASES,1):
 assert valid(premises,goal)
 steps+=['**第'+str(i)+'问。** '+({'1':r'否定r∨s得到¬r∧¬s。','2':r'否定p→(p∧q)得到p∧¬(p∧q)，再化为p与¬p∨¬q。','3':r'两个双条件各拆两个蕴涵，t∧r拆两个单子句；结论否定为¬p∨¬q。','4':r'否定t→(r∧s)得到t∧(¬r∨¬s)。','5':r'否定r∨s得到两个单子句¬r、¬s。'}[str(i)])]+resolvent(clauses,path)
put(19,steps,[r'证明推理须加入结论的否定，而不是结论本身。',r'每次只能消去一对互补文字，空子句与重言子句不可混淆。'])

example('058-2347',[r'第（1）前提p、p→q，结论q。若前提合取真，则p真；条件句要在p真下为真就必须q真，因此假言推理有效。答案四行表中只有11让两前提同时真，而此行结论q也真。',r'第（2）前提p、q→p，结论q。q→p只规定q真时p真，不能从已经知道p真反推q；取pq=10，p=1且0→1=1，而q=0，正是前提真、结论假的反例。',r'将前提合取蕴涵结论，第一式恒真，第二式在10为0。有效性看共同赋值下前提与结论的配合，不是只看前提、结论各自是否有真行。'],[r'p与q→p属于肯定后件结构，不是p与p→q。',r'找反例必须让两个前提一起真。'])
example('059-7397',[r'前两问设p为a被4整除、q为a被2整除。第（1）前提p→q、p，假言推理得q，正确。第（2）前提p→q、q却想得p，是肯定后件；a=2给p假q真，条件句真、第二前提真、结论假，故错误。',r'第（3）设p为去看电影、q为去游泳，前提p∨q、¬p，析取三段论得q，正确，不需把“或”额外解释成互斥。',r'第（4）设p为气温超过30℃、q为游泳、r为看电影。前提p→q、q→¬r，实际可由假言三段论推出p→¬r；题目结论却是逆方向¬r→p，不能由此得到。',r'形式反例pqr=000：0→0真，0→1真，但¬r→p是1→0假。总蕴涵化简为p∨r，其PDNF含下标1、3、4、5、6、7，缺0、2，进一步核验不是重言式。这里不看电影不意味着天气一定热。'],[r'传递后得到p→¬r，不能擅自倒成¬r→p。',r'否定后件有效，肯定后件一般无效，两种句型要分清。'])
example('063-7808',[r'第（1）先把不能走的p分支排掉：①p→s（前提），②¬s（前提），③¬p（①②拒取）；④p∨q（前提），⑤q（③④析取三段论），⑥q→r（前提），⑦r（⑤⑥假言推理）。',r'目标是合取r∧(p∨q)，不是只得到r就结束；把⑦与原前提④作合取引入，得到完整结论。重复使用原前提是允许的。',r'第（2）先用等值置换：¬p∨q等于p→q，r∨¬q经交换等于¬q∨r、即q→r。与前提r→s串接，可由两次假言三段论得到p→s。',r'若按附加前提详细展开第（2）：假设p，顺次由p→q得q、q→r得r、r→s得s，解除p得p→s。转换与附加法所得一致，没有从条件链无条件断定s。'],[r'第（1）最后必须与原析取前提合取，不能漏掉结论后半。',r'r∨¬q代表q→r，箭头前件是q，不是r。'])
example('064-5670',[r'设p为a实数、q为a有理、r为a无理、s为a能表示成分数。原前提是p→(q∨r)、¬s→¬q、p∧¬s，结论r。“不是有理就是无理”在证明中先按析取处理。',r'从第三前提化简出p和¬s。用p与第一前提得q∨r；用¬s与第二前提得¬q；最后q∨r与¬q析取三段论得r。每条需要的前件都已有来源。',r'因此在题给条件下a无理。不能把“无法表示分数”直接当作要证结论跳过前提链；完整链条说明其与有理性、实数分类如何衔接。'],[r'¬s→¬q的否定分别属于两原子命题，不是否定整个条件句。',r'析取q∨r本身不能直接取r，必须同时已有¬q。'])
example('065-5229',[r'设p、q、r、s依次表示小张、小王、小李、小赵看电影。前提(p∧q)→r、¬s∨p、q，结论s→r。小赵的字母是s，不可与小李r混用。',r'为证条件句附加①s。②p由¬s∨p与①析取三段论；③q为原前提；④p∧q由②③合取；⑤r由④与(p∧q)→r假言推理。',r'解除附加假设①，得到s→r。q是原前提，可以在假设s的内部使用；解除s后不能只留下r作无条件结论。'],[r'小张与小王都去才触发小李去，合取前件不能只用一个人。',r'证明的目标是“小赵去则小李去”，不是直接证明小赵已经去。'])
example('066-4733',[r'设p为小张守一垒、q为小李向B队投球、r为A队取胜、s为联赛第一。前提(p∧q)→r、¬r∨s、¬s、p，目标¬q。',r'先由¬r∨s与¬s析取三段论得¬r。为归谬附加q，与原前提p合得p∧q，再由第一条件句得r；与已得¬r形成r∧¬r矛盾。',r'解除附加q，结论¬q。等价的直接路径是由条件与¬r拒取得¬(p∧q)=¬p∨¬q，再用p得到¬q；两条路径共同核对结论，但归谬法必须明确指出新增q及其解除。'],[r'前提¬r∨s与¬s得到的是¬r，不是r。',r'结论¬q的反面假设为q，不是再假设¬q。'])
clauses=[['-q','p'],['-q','s'],['-s','q'],['-s','t'],['-t','s'],['t'],['r'],['-p','-q','-s']]
path=[(6,5,'t'),(9,3,'s'),(10,1,'q'),(11,8,'p'),(10,12,'q'),(9,13,'s')]
example('067-3788',[r'两个双条件各拆成两个方向，t∧r拆成t、r；结论p∧q∧s的否定为¬p∨¬q∨¬s，是一个析取子句，不能误拆成三个否定单子句。']+resolvent(clauses,path)+[r'前提r在这条最短消解链中未用到，但它仍保留在原子句集。一个子集已经不可满足，就足以说明加入其他前提后的全集也不可满足，不需要为了使用每条前提而硬添步骤。'],[r'否定合取后是析取，三文字必须保留在同一子句中。',r'未使用冗余前提不影响消解反证的有效性。'])

